// ── Rumah123: Regex HTML Parse + Filter + Dedup ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const html = $input.first().json.data || $input.first().json.body || '';
if (!html || html.length < 500) {
  console.log('Rumah123: empty or blocked response');
  return [];
}

// ── Strategy 1: Try __NEXT_DATA__ JSON embedded in HTML ──
const nextDataMatch = html.match(/<script[^>]+id=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/);
let listings = [];

if (nextDataMatch) {
  try {
    const nextData = JSON.parse(nextDataMatch[1]);
    // Navigate Next.js page props — structure varies
    const props = nextData?.props?.pageProps;
    const rawListings = props?.listings || props?.data?.listings ||
      props?.searchResult?.listings || props?.results || [];

    if (Array.isArray(rawListings) && rawListings.length > 0) {
      // Use structured data
      for (const item of rawListings) {
        const price = parseInt(String(item.price?.value || item.price || 0).replace(/\D/g, ''));
        if (!price || price < 300000 || price > 800000) continue;

        const locText = [item.address, item.area, item.city, item.title].filter(Boolean).join(' ').toLowerCase();
        if (!locText.includes('surabaya') && !locText.includes('sby')) continue;

        const imgs = (item.photos || item.images || [])
          .map(p => typeof p === 'string' ? p : p?.url || p?.src || '')
          .filter(u => u.startsWith('http')).slice(0, 5);
        if (imgs.length === 0) continue;

        const uid = 'r123_' + (item.id || item.slug || '');
        if (!uid.replace('r123_', '') || staticData.sentIds[uid]) continue;
        staticData.sentIds[uid] = now;

        listings.push({
          json: {
            source: 'rumah123',
            title: item.title || 'Kos Surabaya',
            price,
            location: [item.address, item.area, item.city].filter(Boolean).join(', ') || 'Surabaya',
            url: item.url || item.link || `https://www.rumah123.com/properti/${item.slug}`,
            description: (item.description || '').slice(0, 500),
            images: imgs,
            scraped_at: new Date().toISOString()
          }
        });
      }
      if (listings.length > 0) {
        console.log(`Rumah123 (Next.js): ${listings.length} listings`);
        return listings;
      }
    }
  } catch(e) {
    console.log('Rumah123: Next.js parse failed, falling back to regex:', e.message);
  }
}

// ── Strategy 2: Regex extraction fallback ──
// Extract listing cards — common patterns on Rumah123
const cardPattern = /href=["'](\/properti\/[^"']+)["'][^>]*>[\s\S]{0,2000}?<\/article>/gi;
const pricePattern = /Rp\s*([\d.,]+(?:\.\d+)?)/gi;
const titlePattern = /<h[23][^>]*class="[^"]*(?:card-title|listing-title|property-title)[^"]*"[^>]*>([^<]+)<\/h[23]>/gi;
const imgPattern = /(?:data-src|src)=["'](https?:\/\/(?:images|cdn|photos?|media)[^"']+\.(?:jpg|jpeg|webp|png)(?:\?[^"']*)?)["']/gi;
const adrPattern = /(?:class="[^"]*(?:address|location|area)[^"]*"[^>]*>)([^<]{5,80})</gi;

// Collect all listing URLs from page
const urlMatches = [...html.matchAll(/href=["'](\/properti\/surabaya\/[^"'?#]+)["']/g)]
  .map(m => 'https://www.rumah123.com' + m[1])
  .filter((u, i, arr) => arr.indexOf(u) === i) // unique
  .slice(0, 20);

// Collect all prices on page
const allPrices = [...html.matchAll(/Rp[\s.]*([\d]{3}[\d.,]*)/g)]
  .map(m => parseInt(m[1].replace(/[.,]/g, '')))
  .filter(p => p >= 300000 && p <= 800000);

// Collect all images on page
const allImgs = [...html.matchAll(/https:\/\/(?:cf|img|cdn|s3)[^\s"']*\.(?:jpg|jpeg|webp|png)(?:\?[^"'\s]*)?/g)]
  .map(m => m[0])
  .filter((u, i, arr) => arr.indexOf(u) === i)
  .slice(0, 100);

// Collect titles
const allTitles = [...html.matchAll(/<(?:h[23]|a)[^>]*(?:title|heading|card-title)[^>]*>\s*([^<]{10,100})\s*<\/(?:h[23]|a)>/g)]
  .map(m => m[1].trim())
  .filter(t => t.toLowerCase().includes('kos') || t.toLowerCase().includes('kamar'));

// Pair them up — best effort
const pairCount = Math.min(urlMatches.length, allPrices.length, 5);
for (let i = 0; i < pairCount; i++) {
  const uid = 'r123_' + urlMatches[i].split('/').slice(-2).join('_');
  if (staticData.sentIds[uid]) continue;
  staticData.sentIds[uid] = now;

  const imgs = allImgs.slice(i * 3, i * 3 + 5);
  if (imgs.length === 0) continue;

  listings.push({
    json: {
      source: 'rumah123',
      title: allTitles[i] || 'Kos Surabaya',
      price: allPrices[i],
      location: 'Surabaya',
      url: urlMatches[i],
      description: '',
      images: imgs,
      scraped_at: new Date().toISOString()
    }
  });
}

console.log(`Rumah123 (regex): ${listings.length} listings`);
return listings;

